// Task-only loopback receiver for inspecting downloads generated by the actual UI.
// Never included in the website build. Only fixed names and local test origins are allowed.
import http from 'node:http';
import { writeFile } from 'node:fs/promises';
const origins = new Set(['http://127.0.0.1:5174', 'http://127.0.0.1:5173']);
const suffix = process.argv[2] === 'v2' ? '-v2' : '';
const port = suffix ? 5187 : 5186;
const server = http.createServer(async (req, res) => {
  const origin = req.headers.origin;
  if (!origins.has(origin)) { res.writeHead(403).end(); return; }
  res.setHeader('Access-Control-Allow-Origin', origin);
  res.setHeader('Vary', 'Origin');
  if (req.method === 'OPTIONS') { res.setHeader('Access-Control-Allow-Methods', 'POST'); res.setHeader('Access-Control-Allow-Headers', 'Content-Type'); res.writeHead(204).end(); return; }
  const match = req.url?.match(/^\/capture\/(pdf|docx)$/);
  if (req.method !== 'POST' || !match) { res.writeHead(404).end(); return; }
  let size = 0; const chunks = [];
  try {
    for await (const chunk of req) { size += chunk.length; if (size > 80 * 1024 * 1024) { res.writeHead(413).end(); req.destroy(); return; } chunks.push(chunk); }
    const data = Buffer.concat(chunks);
    if (match[1] === 'pdf' ? data.subarray(0,5).toString() !== '%PDF-' : data.subarray(0,2).toString() !== 'PK') { res.writeHead(415).end(); return; }
    await writeFile(new URL(`artifacts/ui-export${suffix}.${match[1]}`, import.meta.url), data);
    res.writeHead(200, { 'Content-Type': 'application/json' }).end(JSON.stringify({ saved: true, bytes: size }));
    console.log(`Saved UI ${match[1]}: ${size} bytes`);
  } catch (error) { res.writeHead(500).end(); console.error(error.message); }
});
server.listen(port, '127.0.0.1', () => console.log(`Export inspection receiver http://127.0.0.1:${port} (loopback only)`));
